import type {PackagePolicy} from './packages'

export interface SaveEnterprisePolicyPayload {
  enterprise_slug: string
  context: string
  add_spdx_ids: string[]
  delete_spdx_ids: string[]
  add_packages: Array<Pick<PackagePolicy, 'name' | 'package_manager'>>
  delete_packages: Array<Pick<PackagePolicy, 'name' | 'package_manager'>>
}

export interface SaveEnterprisePolicyResponse {
  failed_spdx_ids?: string[]
}

// The save endpoint can return a 2xx with `failed_spdx_ids` listing SPDX IDs the server
// declined to add (e.g. unknown/invalid). The response shape is otherwise untyped, so we
// narrow defensively here and let both the mutation hook and the page consume the result.
export function extractFailedSpdxIds(data: unknown): string[] {
  if (typeof data !== 'object' || data === null) return []
  const maybeIds = (data as {failed_spdx_ids?: unknown}).failed_spdx_ids
  if (!Array.isArray(maybeIds)) return []
  return maybeIds.filter((v): v is string => typeof v === 'string')
}

export interface SaveRepositoryPolicyPayload {
  repository_slug: string
  organization_slug: string
  context: string
  delete_spdx_ids: string[]
  delete_packages: Array<Pick<PackagePolicy, 'name' | 'package_manager'>>
}
