import {useState} from 'react'
import {Banner} from '@primer/react'
import type {AddAllowedLicensesMutation} from '../../types/mutations'
import {useAnnounceBanner} from '../../hooks/use-announce-banner'
import {LicensePolicyAddDialog} from './LicensePolicyAddDialog'

interface LicensePolicyBannerProps {
  variant: React.ComponentProps<typeof Banner>['variant']
  title: string
  description: string
  onDismiss?: () => void
  failedLicenses?: string[]
  addAllowedLicensesMutation?: AddAllowedLicensesMutation
}

const invalidSpdxBanner = (
  <Banner
    variant="critical"
    title="Invalid SPDX identifiers"
    hideTitle
    description="Invalid SPDX identifiers. Correct each identifier to add licenses to the policy."
    className="tmp-mb-3"
  />
)

export function LicensePolicyBanner({
  variant,
  title,
  description,
  onDismiss,
  failedLicenses,
  addAllowedLicensesMutation,
}: LicensePolicyBannerProps) {
  const [showRetryDialog, setShowRetryDialog] = useState(false)

  useAnnounceBanner(`${title}. ${description}`, {assertive: variant === 'critical'})

  return (
    <>
      <Banner
        variant={variant}
        title={title}
        hideTitle
        description={description}
        onDismiss={onDismiss}
        primaryAction={
          failedLicenses && addAllowedLicensesMutation ? (
            <Banner.PrimaryAction onClick={() => setShowRetryDialog(true)}>View failed licenses</Banner.PrimaryAction>
          ) : undefined
        }
        className="tmp-mb-3"
      />
      {failedLicenses && addAllowedLicensesMutation && (
        <LicensePolicyAddDialog
          key={failedLicenses.join('\n')}
          isOpen={showRetryDialog}
          onClose={() => {
            setShowRetryDialog(false)
            onDismiss?.()
          }}
          addAllowedLicensesMutation={addAllowedLicensesMutation}
          initialValue={failedLicenses.join('\n')}
          headerContent={invalidSpdxBanner}
        />
      )}
    </>
  )
}
