import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListItemTrailingBadge} from '@github-ui/list-view/ListItemTrailingBadge'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemMetadata} from '@github-ui/list-view/ListItemMetadata'
import {TrashIcon} from '@primer/octicons-react'
import {IconButton, BranchName} from '@primer/react'
import {clsx} from 'clsx'
import type {ReactElement, ReactNode} from 'react'

interface BaseListItemProps {
  title: string
  description?: string
  isSelected: boolean
  isWildcard: boolean
  hasCheckboxes: boolean
  label?: ReactElement<typeof ListItemTrailingBadge>
  trailingContent?: ReactNode
  onSelect: () => void
  onDelete?: () => void
}

export function BaseListItem({
  title,
  description,
  isSelected,
  isWildcard,
  hasCheckboxes,
  label,
  trailingContent,
  onSelect,
  onDelete,
}: BaseListItemProps) {
  const renderDeleteButton = () => {
    if (!onDelete) return null
    return (
      <IconButton
        data-testid={`delete-button-${title}`}
        onClick={onDelete}
        icon={TrashIcon}
        size="small"
        variant="invisible"
        aria-label={`Delete ${title}`}
      />
    )
  }

  const listItemClassName = clsx({
    'pl-2': !hasCheckboxes,
  })

  return (
    <ListItem
      title={
        <ListItemTitle
          value={
            isWildcard ? (
              <>
                {'Wildcard pattern: '}
                <BranchName className="fgColor-muted" style={{fontWeight: 'normal'}}>
                  {title}
                </BranchName>
              </>
            ) : (
              title
            )
          }
          trailingBadges={label ? [label] : undefined}
        />
      }
      isSelected={isSelected}
      onSelect={() => onSelect()}
      metadata={
        <ListItemMetadata>
          {trailingContent}
          {renderDeleteButton()}
        </ListItemMetadata>
      }
      className={listItemClassName}
    >
      <ListItemMainContent>
        {description && <ListItemDescription>{description}</ListItemDescription>}
      </ListItemMainContent>
    </ListItem>
  )
}
