import {SelectContainer} from '@github-ui/simple-select'
import {announce} from '@primer/live-region-element'
import {SearchIcon} from '@primer/octicons-react'
import {
  ActionList,
  Button,
  Heading,
  SelectPanel,
  useIsomorphicLayoutEffect,
  useRovingTabIndex,
  VisuallyHidden,
} from '@primer/react'
import {FilteredActionList, FilteredActionListLoadingTypes} from '@primer/react/experimental'
import {useCallback, useEffect, useId, useRef, useState} from 'react'

import styles from './BulkSelector.module.css'
import {BulkSelectorBody} from './components/BulkSelectorBody'
import type {BulkSelectorProps, GroupMetaData, Items} from './types'

const CONTAINER_CONTEXT_VALUE = {selectionAttribute: 'aria-checked'} as const
const ANNOUNCE_DELAY_MS = 500
const DEBOUNCE_DELAY = 300 // ms

export function BulkSelector({
  items,
  label,
  title = 'Select an item',
  onSelect,
  renderText,
  onClose: externalOnClose,
  onCancel: externalOnCancel,
  open,
  onOpen,
  renderAnchor,
  onSelectionChange,
  buttonProps,
  outsideClick = 'save',
  onEscape = 'save',
  dialogProps,
  footerButtons,
  groupMetadata,
  filterValue: externalFilterValue,
  onFilterChange,
  inputRef: providedInputRef,
  loading = false,
  placeholderText,
  loadingType = FilteredActionListLoadingTypes.bodySpinner,
  fullScreenOnNarrow = true,
  height,
  subtitle,
  message,
}: BulkSelectorProps) {
  const [tempItems, setTempItems] = useState<Array<Items & {visible: boolean}>>(
    items.map(item => ({...item, visible: item.visible ?? true})),
  )
  const [tempGroupMetadata, setTempGroupMetadata] = useState<GroupMetaData[]>(groupMetadata)
  const [prevItems, setPrevItems] = useState(items)
  const prevGroupMetadataRef = useRef(groupMetadata)
  const [bodyHeight, setBodyHeight] = useState(0)
  // eslint-disable-next-line @eslint-react/naming-convention/use-state
  const [filterValue, setInternalFilterValue] = useState<string>(externalFilterValue || '')
  const effectiveFilterValue = externalFilterValue !== undefined ? externalFilterValue : filterValue

  const ref = useRef<HTMLInputElement | null>(null)
  const inputRef = providedInputRef ?? ref
  const bodyWrapperRef = useRef<HTMLDivElement>(null)
  const buttonRef = useRef<HTMLButtonElement>(null)
  const debounceTimerRef = useRef<NodeJS.Timeout | null>(null)
  const listboxRef = useRef<HTMLUListElement>(null)

  useRovingTabIndex({containerRef: listboxRef as React.RefObject<HTMLElement>, preventScroll: false}, [
    tempGroupMetadata,
    open,
    tempItems,
  ])

  const showBodyLoader = loading && loadingType.appearsInBody

  const getFilteredItems = useCallback(
    (filter: string, currentItems?: Items[]) => {
      const itemsToFilter = currentItems || tempItems
      if (!filter || onFilterChange) return itemsToFilter || []
      const matchingGroupIds =
        tempGroupMetadata
          ?.filter(group => group.label?.toLowerCase().includes(filter.toLowerCase()))
          .map(group => group.id) || []

      return (itemsToFilter || []).filter(
        item =>
          item.label.toLowerCase().includes(filter.toLowerCase()) ||
          (item.description !== undefined && item.description.toLowerCase().includes(filter.toLowerCase())) ||
          matchingGroupIds.includes(item.groupId),
      )
    },
    [tempItems, onFilterChange, tempGroupMetadata],
  )

  if (items !== prevItems) {
    setPrevItems(items)
    if (onSelectionChange) {
      setTempItems(items.map(item => ({...item, visible: item.visible !== false})))
    } else {
      const filteredItems = getFilteredItems(effectiveFilterValue, items)
      setTempItems(items.map(item => ({...item, visible: filteredItems.includes(item)})))
    }
  }

  useEffect(() => {
    if (groupMetadata !== prevGroupMetadataRef.current) {
      prevGroupMetadataRef.current = groupMetadata
      setTempGroupMetadata(groupMetadata)
    }
  }, [groupMetadata])

  // Cleanup debounce timer on unmount
  const cleanup = () => {
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current)
      debounceTimerRef.current = null
    }
  }

  useEffect(() => () => cleanup(), [])

  const loadingTimerRef = useRef<NodeJS.Timeout | null>(null)
  const loadingRef = useRef(loading)
  useEffect(() => {
    loadingRef.current = loading
  }, [loading])

  const justOpenedRef = useRef(false)
  useEffect(() => {
    if (open) {
      justOpenedRef.current = true
    }
  }, [open])

  // Announce loading state to screen readers
  useEffect(() => {
    if (!open) return
    if (loading) {
      loadingTimerRef.current = setTimeout(() => {
        if (loadingRef.current) {
          announce('Loading.', {delayMs: 0})
        }
      }, ANNOUNCE_DELAY_MS)
    }
    return () => {
      if (loadingTimerRef.current) {
        clearTimeout(loadingTimerRef.current)
        loadingTimerRef.current = null
      }
    }
  }, [loading, open])

  const onInputChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const value = e.target.value
      if (externalFilterValue === undefined) {
        setInternalFilterValue(value)
      }

      // In controlled mode, fire onFilterChange immediately so the parent
      // can update the prop and keep the input responsive.
      if (onFilterChange && externalFilterValue !== undefined) {
        onFilterChange(value, e)
        return
      }

      // Clear existing debounce timer
      if (debounceTimerRef.current) {
        cleanup()
      }

      if (onFilterChange) {
        debounceTimerRef.current = setTimeout(() => {
          onFilterChange(value, e)
        }, DEBOUNCE_DELAY)
      } else {
        debounceTimerRef.current = setTimeout(() => {
          const filteredIds = new Set(getFilteredItems(value).map(i => i.id))
          setTempItems(prev => prev.map(item => ({...item, visible: filteredIds.has(item.id)})))
        }, DEBOUNCE_DELAY)
      }
    },
    [getFilteredItems, onFilterChange, externalFilterValue],
  )

  useIsomorphicLayoutEffect(() => {
    if (bodyWrapperRef.current) {
      const h = bodyWrapperRef.current.clientHeight
      if (h > 0) setBodyHeight(h)
    }
  }, [open, loading])

  const listId = useId()
  const inputDescriptionTextId = useId()

  const headingId = useId()
  const subtitleId = useId()
  const selectedItems = tempItems.filter(item => item.selected)
  const visibleItems = tempItems.filter(item => item.visible)
  const selectedCountRef = useRef(selectedItems.length)

  useEffect(() => {
    selectedCountRef.current = selectedItems.length
  }, [selectedItems.length])

  const hasMessage =
    visibleItems.length === 0 || (!!message && (message.variant !== 'empty' || visibleItems.length === 0))

  // Announce list updates to screen readers when visible item count changes or a message is shown
  useEffect(() => {
    if (!open || loading) return

    if (justOpenedRef.current) {
      justOpenedRef.current = false
      return
    }

    if (hasMessage && message) {
      const text =
        typeof message.body === 'string' && message.body ? `${message.title}. ${message.body}` : message.title
      announce(text, {delayMs: ANNOUNCE_DELAY_MS})
    } else if (visibleItems.length === 0) {
      announce('No items found', {delayMs: ANNOUNCE_DELAY_MS})
    } else {
      const count = visibleItems.length
      const selected = selectedCountRef.current
      announce(`${count} item${count !== 1 ? 's' : ''} available, ${selected} selected.`, {
        delayMs: ANNOUNCE_DELAY_MS,
      })
    }
  }, [visibleItems.length, message, open, loading, hasMessage])

  function getMessage() {
    if (visibleItems.length === 0 && !message) {
      return (
        <SelectPanel.Message variant="empty" title="No items found">
          Try a different search term
        </SelectPanel.Message>
      )
    } else if (message) {
      return (
        <SelectPanel.Message
          title={message.title}
          variant={message.variant}
          icon={message.icon}
          action={message.action}
        >
          {message.body}
        </SelectPanel.Message>
      )
    }
    return undefined
  }

  const resetTempState = useCallback(() => {
    setTempItems(items.map(item => ({...item, visible: true})))
    setTempGroupMetadata(groupMetadata)
    if (externalFilterValue === undefined) {
      setInternalFilterValue('')
    }
  }, [items, groupMetadata, externalFilterValue])

  const handleAction = (action: 'save' | 'cancel') => {
    cleanup()
    if (action === 'save') {
      externalOnClose(tempItems, tempGroupMetadata)
    } else {
      externalOnClose(items, groupMetadata)
      externalOnCancel?.()
      resetTempState()
    }
  }

  const selectSave = () => handleAction('save')
  const selectCancel = () => handleAction('cancel')

  const handleControlledItems = (selection: Items[], updatedGroupMetadata?: GroupMetaData[]) => {
    const updatedItems = tempItems.map(item => {
      const isSelected = selection.some(selectedItem => selectedItem.id === item.id)
      return isSelected ? {...item, selected: true} : {...item, selected: false}
    })

    if (onSelectionChange) {
      onSelectionChange(selection, updatedItems, updatedGroupMetadata as GroupMetaData[])
    } else {
      setTempGroupMetadata(updatedGroupMetadata as GroupMetaData[])
      const filteredItems = getFilteredItems(effectiveFilterValue, updatedItems)
      setTempItems(updatedItems.map(item => ({...item, visible: filteredItems.includes(item)})))
    }
  }

  const onClose = (gesture: string) => {
    if (gesture === 'click-outside' || gesture === 'anchor-click' || gesture === 'close-button') {
      handleAction(outsideClick)
    } else if (gesture === 'escape') {
      handleAction(onEscape)
    }
  }

  const defaultAnchorText = renderText
    ? renderText()
    : `${label}${!selectedItems.length ? '' : `: ${selectedItems.map(item => item.label).join(', ')}`}`

  const anchorElement = renderAnchor ? (
    // eslint-disable-next-line react-hooks/refs
    renderAnchor({
      onClick: () => {
        if (!open) onOpen()
      },
      'aria-haspopup': 'dialog',
      'aria-expanded': open,
      ref: buttonRef,
      ...buttonProps,
    })
  ) : (
    <Button
      ref={buttonRef}
      variant="default"
      onClick={() => {
        if (!open) {
          onOpen()
        }
      }}
      aria-haspopup="dialog"
      aria-expanded={open}
      {...buttonProps}
    >
      {defaultAnchorText}
    </Button>
  )

  return (
    <>
      {anchorElement}
      <SelectContainer
        headingId={headingId}
        open={open}
        anchorRef={buttonRef}
        returnFocusRef={buttonRef}
        onClose={onClose}
        variant="modal"
        dialogProps={dialogProps}
        title={title}
        selectSave={selectSave}
        selectCancel={selectCancel}
        footerButtons={footerButtons}
        height={height}
        initialFocusRef={inputRef}
      >
        <div data-container="modal" className={styles.Wrapper}>
          <FilteredActionList.Input
            inputRef={inputRef}
            value={effectiveFilterValue}
            onInputChange={onInputChange}
            placeholderText={placeholderText}
            listId={listId}
            inputDescriptionTextId={inputDescriptionTextId}
            loading={loading && !loadingType.appearsInBody}
            fullScreenOnNarrow={fullScreenOnNarrow}
            aria-expanded={undefined}
            role={undefined}
            aria-autocomplete={undefined}
            className={styles.TextInput}
            aria-label={placeholderText ?? 'Filter items'}
            leadingVisual={SearchIcon}
            contrast
          />
          <VisuallyHidden id={inputDescriptionTextId}>Items will be filtered as you type</VisuallyHidden>
          {subtitle ? (
            <Heading as="h2" id={subtitleId} className={styles.Subtitle}>
              {typeof subtitle === 'function' ? subtitle(selectedItems.length) : subtitle}
            </Heading>
          ) : null}
          <div className={styles.SelectBodyWrapper} ref={bodyWrapperRef}>
            {showBodyLoader ? (
              // eslint-disable-next-line primer-react/no-system-props
              <FilteredActionList.BodyLoader loadingType={loadingType} height={bodyHeight} />
            ) : hasMessage ? (
              getMessage()
            ) : (
              <ActionList.ContainerContext value={CONTAINER_CONTEXT_VALUE}>
                <ActionList
                  ref={listboxRef}
                  role="tree"
                  aria-multiselectable="true"
                  selectionVariant="multiple"
                  aria-label={title}
                  aria-describedby={subtitle ? subtitleId : undefined}
                  variant="full"
                  disableFocusZone
                  id={listId}
                >
                  <BulkSelectorBody
                    items={tempItems}
                    onItemSelect={onSelect}
                    onSelectionChange={handleControlledItems}
                    groupMetadata={tempGroupMetadata}
                    filterActive={effectiveFilterValue.length > 0}
                  />
                </ActionList>
              </ActionList.ContainerContext>
            )}
          </div>
        </div>
      </SelectContainer>
    </>
  )
}
