import {useEffect} from 'react'
import {announce} from '@github-ui/aria-live'

// Primer's `Banner` is not wrapped in a live region, so banners that appear in
// response to an action (save, revert, validation errors) are silent for
// assistive technology. Use `assertive` for error/critical banners so they interrupt.
export function useAnnounceBanner(message: string | undefined, options?: {assertive?: boolean}) {
  const assertive = options?.assertive ?? false

  useEffect(() => {
    if (message) {
      announce(message, {assertive})
    }
  }, [message, assertive])
}
