import {useState} from 'react'
import {ControlGroup} from '@github-ui/control-group'
import {ShieldLockIcon} from '@primer/octicons-react'
import {AnchoredOverlay, Button, Heading, Stack, Text} from '@primer/react'

type LicensePolicyOverviewSectionProps = {
  heading: string
  subtitle: string
  hasAccess?: boolean
  items: Array<{
    title: string
    description: string
    href: string
    icon?: React.ReactNode
    value?: string
  }>
}

export const LicensePolicyOverviewSection = ({
  heading,
  subtitle,
  hasAccess,
  items,
}: LicensePolicyOverviewSectionProps) => (
  <Stack as="section" gap="normal">
    <Stack as="header" gap="none">
      <Heading as="h3" className="h4">
        {heading}
      </Heading>
      <span className="fgColor-muted">{subtitle}</span>
    </Stack>

    <ControlGroup>
      {items.map(({title, description, href, icon, value}) => {
        if (hasAccess)
          return (
            <ControlGroup.LinkItem key={title} href={href} leadingIcon={icon} value={value}>
              <ControlGroup.Title>{title}</ControlGroup.Title>
              <ControlGroup.Description>{description}</ControlGroup.Description>
            </ControlGroup.LinkItem>
          )

        return (
          <ControlGroup.Item key={title} leadingIcon={icon}>
            <ControlGroup.Title>{title}</ControlGroup.Title>
            <ControlGroup.Description>{description}</ControlGroup.Description>
            <ControlGroup.Custom>
              <NoAccessButton />
            </ControlGroup.Custom>
          </ControlGroup.Item>
        )
      })}
    </ControlGroup>
  </Stack>
)

const NoAccessButton = () => {
  const [open, setOpen] = useState(false)

  return (
    <AnchoredOverlay
      align="end"
      side="outside-top"
      width="small"
      open={open}
      onOpen={() => setOpen(true)}
      onClose={() => setOpen(false)}
      renderAnchor={props => (
        <Button size="small" variant="invisible" leadingVisual={ShieldLockIcon} {...props}>
          No access
        </Button>
      )}
    >
      <Stack padding="normal">
        <Text size="small">You do not have access to manage this. Contact your admin to gain access.</Text>
      </Stack>
    </AnchoredOverlay>
  )
}
