import {useCallback, useMemo} from 'react'

import {LicensePolicyPage} from '../LicensePolicyPage/LicensePolicyPage'
import type {RepositoryLicensePolicyResponse} from '../../types/policies'
import {toGenericLicensePolicyResponse} from '../../types/policies'
import {PolicyLevel} from '../../types/policy-levels'
import {useUserPermissions} from '../../context/UserPermissionsContext'
import {PolicyEditMode, usePolicyEditMode} from '../../context/PolicyEditModeContext'

import type {DeleteAllowedLicensesMutation, DeletePackageExceptionsMutation} from '../../types/mutations'
import {useDeleteAllowedLicensesFromRepositoryMutation} from '../../hooks/use-delete-allowed-licenses-mutation'
import {useDeletePackageExceptionsFromRepositoryMutation} from '../../hooks/use-delete-package-exceptions-mutation'
import {usePolicyLicensesDraftState} from '../../hooks/use-policy-licenses-draft-state'
import {usePolicyPackagesDraftState} from '../../hooks/use-policy-packages-draft-state'
import {useSaveRepositoryPolicyMutation} from '../../hooks/use-save-repository-policy-mutation'

export function RepositoryLicensePolicyPage({
  preview,
  data,
}: {
  preview: boolean
  data: RepositoryLicensePolicyResponse
}) {
  const deleteAllowedLicensesMutation = useDeleteAllowedLicensesFromRepositoryMutation()
  const deletePackageExceptionsMutation = useDeletePackageExceptionsFromRepositoryMutation()

  const {canManagePolicy} = useUserPermissions()

  const editMode = usePolicyEditMode()
  const isDraftMode = editMode === PolicyEditMode.Draft

  const {allLicenses, deleteSpdxIds, stageDeleteLicenses, resetLicensesFromUpstream} = usePolicyLicensesDraftState(
    PolicyLevel.Repository,
    data.allowed,
  )

  const {allPackages, deletePackages, stageDeletePackages, resetPackagesFromUpstream} = usePolicyPackagesDraftState(
    PolicyLevel.Repository,
    data.packages,
  )

  const resetAllFromUpstream = useCallback(() => {
    resetLicensesFromUpstream()
    resetPackagesFromUpstream()
  }, [resetLicensesFromUpstream, resetPackagesFromUpstream])

  const saveRepositoryPolicyMutation = useSaveRepositoryPolicyMutation()

  const policyData = useMemo(
    () => ({
      ...toGenericLicensePolicyResponse(PolicyLevel.Repository, data),
      allowed: isDraftMode ? allLicenses : data.allowed,
      packages: isDraftMode ? allPackages : data.packages,
    }),
    [data, isDraftMode, allLicenses, allPackages],
  )

  const onSaveDraftPolicy = () => {
    saveRepositoryPolicyMutation.mutate({
      context: 'distributed',
      deleteSpdxIds,
      deletePackages,
    })
  }

  const deleteAllowedLicensesMutationToUse: DeleteAllowedLicensesMutation = useMemo(() => {
    if (!isDraftMode) return deleteAllowedLicensesMutation

    return {
      mutate: ({spdxIds}) => {
        stageDeleteLicenses(spdxIds)
      },
      isError: false,
      isPending: false,
      reset: () => {},
    }
  }, [deleteAllowedLicensesMutation, isDraftMode, stageDeleteLicenses])

  const deletePackageExceptionsMutationToUse: DeletePackageExceptionsMutation = useMemo(() => {
    if (!isDraftMode) return deletePackageExceptionsMutation

    return {
      mutate: ({packages}) => {
        stageDeletePackages(packages)
      },
      isError: false,
      isPending: false,
      reset: () => {},
    }
  }, [deletePackageExceptionsMutation, isDraftMode, stageDeletePackages])

  const draftSaveRevertControls =
    isDraftMode && canManagePolicy
      ? {
          addCount: 0,
          deleteCount: deleteSpdxIds.length + deletePackages.length,
          onSave: onSaveDraftPolicy,
          onRevert: resetAllFromUpstream,
          resetOnRevert: () => {
            saveRepositoryPolicyMutation.reset()
          },
          saveMutation: saveRepositoryPolicyMutation,
        }
      : undefined

  return (
    <LicensePolicyPage
      title="License policy"
      preview={preview}
      data={policyData}
      pageDescription="This policy is a composite of your enterprise policy and amendments granted to your repository. Only amendments specific to your repository can be managed on this page."
      licensesDescription="Dependencies with these licenses can be used without review."
      exceptionsDescription="These packages can be used without review."
      enterpriseName={data.enterprise_name}
      enterpriseSlug={data.enterprise_slug}
      deleteAllowedLicensesMutation={deleteAllowedLicensesMutationToUse}
      deletePackageExceptionsMutation={deletePackageExceptionsMutationToUse}
      draftSaveRevert={draftSaveRevertControls}
    />
  )
}
