import {reactFetchJSON} from '@github-ui/verified-fetch'
import type {SaveEnterprisePolicyPayload, SaveRepositoryPolicyPayload} from '../types/save-policy'
import {enterpriseSingleLicensePolicyRoute, repositoryLicensePolicyRoute} from '../routes/license-policy-route'

export async function saveEnterprisePolicy(payload: SaveEnterprisePolicyPayload) {
  const saveEnterprisePolicyRoute = getEnterpriseSavePolicyRoute(payload.enterprise_slug)

  const body: Record<string, unknown> = {context: payload.context}
  if (payload.add_spdx_ids.length > 0) body.add_spdx_ids = payload.add_spdx_ids
  if (payload.delete_spdx_ids.length > 0) body.delete_spdx_ids = payload.delete_spdx_ids
  if (payload.add_packages.length > 0) body.add_packages = payload.add_packages
  if (payload.delete_packages.length > 0) body.delete_packages = payload.delete_packages

  const response = await reactFetchJSON(saveEnterprisePolicyRoute, {
    method: 'PUT',
    body,
  })

  if (!response.ok) {
    let errorData: unknown
    try {
      errorData = await response.json()
    } catch {
      // If we can't parse JSON, use the status text
      throw new Error(response.statusText)
    }

    const serverMessage = getErrorMessageFromResponseBody(errorData)
    const error = new Error(serverMessage || response.statusText)
    Object.assign(error, {data: errorData})
    throw error
  }

  const data = await response.json()
  return data
}

export async function saveRepositoryPolicy(payload: SaveRepositoryPolicyPayload) {
  const saveRepositoryPolicyRoute = getRepositorySavePolicyRoute(payload.organization_slug, payload.repository_slug)

  const body: Record<string, unknown> = {context: payload.context}
  if (payload.delete_spdx_ids.length > 0) body.delete_spdx_ids = payload.delete_spdx_ids
  if (payload.delete_packages.length > 0) body.delete_packages = payload.delete_packages

  const response = await reactFetchJSON(saveRepositoryPolicyRoute, {
    method: 'PUT',
    body,
  })

  if (!response.ok) {
    let errorData: unknown
    try {
      errorData = await response.json()
    } catch {
      // If we can't parse JSON, use the status text
      throw new Error(response.statusText)
    }

    const serverMessage = getErrorMessageFromResponseBody(errorData)
    const error = new Error(serverMessage || response.statusText)
    Object.assign(error, {data: errorData})
    throw error
  }

  const data = await response.json()
  return data
}

function getErrorMessageFromResponseBody(body: unknown): string | undefined {
  if (typeof body === 'string') return body
  if (typeof body !== 'object' || body === null) return undefined

  const record = body as Record<string, unknown>
  const topLevel = record.error ?? record.message

  if (typeof topLevel === 'string') return topLevel
  if (typeof topLevel === 'object' && topLevel !== null) {
    const nested = topLevel as Record<string, unknown>
    if (typeof nested.message === 'string') return nested.message
  }

  return undefined
}

function getEnterpriseSavePolicyRoute(enterprise_slug: string) {
  return enterpriseSingleLicensePolicyRoute.generatePath({business: enterprise_slug})
}

function getRepositorySavePolicyRoute(organization_slug: string, repository_slug: string) {
  return repositoryLicensePolicyRoute.generatePath({organization: organization_slug, repository: repository_slug})
}
