import {Textarea, Button} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {useState} from 'react'
import type {AddAllowedLicensesMutation} from '../../types/mutations'

interface LicensePolicyAddDialogProps {
  isOpen: boolean
  onClose: () => void
  addAllowedLicensesMutation?: AddAllowedLicensesMutation
  initialValue?: string
  headerContent?: React.ReactNode
}

export function LicensePolicyAddDialog({
  isOpen,
  onClose,
  addAllowedLicensesMutation,
  initialValue = '',
  headerContent,
}: LicensePolicyAddDialogProps) {
  const [newLicenses, setNewLicenses] = useState(initialValue)

  // Custom close handler that clears the dialog state
  const handleClose = () => {
    setNewLicenses(initialValue) // Reset to initial value on close
    onClose() // Call parent close handler
  }

  // Handler for updating the new license input value
  const handleLicensesChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setNewLicenses(e.target.value)
  }

  // Handler for adding new licenses to the enterprise policy
  const handleAddLicenses = () => {
    if (!addAllowedLicensesMutation) {
      return
    }

    // Parse new licenses from textarea (one per line, trim whitespace, filter empty lines)
    const parsedLicenseList = newLicenses
      .split('\n')
      .map(license => license.trim())
      .filter(license => license.length > 0)

    addAllowedLicensesMutation.mutate({
      spdxIds: parsedLicenseList,
      context: 'distributed',
      onClose: handleClose,
    })
  }

  if (!isOpen) return null

  return (
    <Dialog title="Add licenses manually" onClose={handleClose}>
      <div className="tmp-pt-3 tmp-px-3">
        {headerContent}
        <Textarea
          block
          value={newLicenses}
          onChange={handleLicensesChange}
          rows={4}
          maxLength={5000}
          resize="vertical"
          placeholder="Enter valid SPDX license identifiers"
          aria-label="SPDX license identifiers, one per line"
          data-1p-ignore="true"
          autoComplete="off"
        />
        <p className="color-fg-muted tmp-mt-2 tmp-mb-0">Separate each license identifier on its own line</p>
      </div>
      <Dialog.Footer>
        <Button onClick={handleClose}>Cancel</Button>
        <Button
          variant="primary"
          onClick={handleAddLicenses}
          loading={addAllowedLicensesMutation?.isPending}
          disabled={newLicenses.trim().length === 0 || !addAllowedLicensesMutation}
        >
          Add
        </Button>
      </Dialog.Footer>
    </Dialog>
  )
}
