import {Dialog} from '@primer/react/experimental'
import {PolicyLevel} from '../../types/policy-levels'
import {ItemType} from '../../types/licenses'
import pluralize from 'pluralize'
import {useMemo} from 'react'

interface LicensePolicyDeleteDialogProps {
  isOpen: boolean
  itemName?: string
  itemType: ItemType
  onClose: () => void
  onConfirm: () => void
  policyLevel: PolicyLevel
}

export function LicensePolicyDeleteDialog({
  isOpen,
  itemName,
  itemType,
  onClose,
  onConfirm,
  policyLevel,
}: LicensePolicyDeleteDialogProps) {
  const itemLabel = useMemo(
    () => (policyLevel === PolicyLevel.Repository ? itemType : pluralize(itemType)),
    [itemType, policyLevel],
  )

  const buttonLabel = useMemo(() => {
    if (itemType === ItemType.Package) {
      return policyLevel === PolicyLevel.Repository ? 'exception' : 'exceptions'
    }
    return itemLabel
  }, [itemType, itemLabel, policyLevel])

  const enterpriseLevelBody = `Selected ${itemLabel} will be deleted. New license compliance alerts may be generated from repositories that are already using the selected ${
    itemType === ItemType.License ? itemLabel : 'packages'
  }.`
  const repositoryLevelBody = `Are you sure you want to delete ${itemName} from the license policy? Once it has been deleted, a new exception request from enterprise reviewers will be required to use this ${
    itemType === ItemType.License ? itemLabel : 'package'
  }.`

  if (!isOpen) return null

  return (
    <Dialog
      title={`Delete ${itemLabel} from policy`}
      onClose={onClose}
      footerButtons={[
        {buttonType: 'default', content: 'Cancel', onClick: onClose},
        {buttonType: 'danger', content: `Delete ${buttonLabel}`, onClick: onConfirm},
      ]}
    >
      {policyLevel === PolicyLevel.Enterprise && enterpriseLevelBody}
      {policyLevel === PolicyLevel.Repository && repositoryLevelBody}
    </Dialog>
  )
}
