import {useCallback, useEffect, useMemo, useState} from 'react'
import {Banner, Button, FormControl, Stack, TextInput, UnderlineNav} from '@primer/react'
import {Link, useBeforeUnload} from '@github-ui/react-router'
import {useSearchParams} from '@github-ui/use-navigate'
import {useStableCallback} from '@github-ui/use-stable-callback'

import {LicensePolicyHeader} from '../LicensePolicyPage/LicensePolicyHeader'
import {LicensePolicyAllowedLicenses} from '../LicensePolicyPage/LicensePolicyAllowedLicenses'
import {LicensePolicyAddDialog} from '../LicensePolicyPage/LicensePolicyAddDialog'
import {LicensePolicyPicker} from '../LicensePolicyPage/LicensePolicyPickerDialog'
import type {MenuItemConfig} from '../BaseListView/BaseListHeader'
import {LicensePolicyPackageExceptions} from '../LicensePolicyPage/LicensePolicyPackageExceptions'
import type {LicensePolicyResponse} from '../../types/policies'
import type {
  AddAllowedLicensesMutation,
  DeleteAllowedLicensesMutation,
  AddPackageExceptionsMutation,
  DeletePackageExceptionsMutation,
} from '../../types/mutations'
import {useUserPermissions} from '../../context/UserPermissionsContext'
import {PolicyEditMode, usePolicyEditMode} from '../../context/PolicyEditModeContext'
import {useAnnounceBanner} from '../../hooks/use-announce-banner'

import styles from '../../routes/LicensePolicy.module.css'
import {PackageExceptionsAddDialog} from '../PackageExceptions/PackageExceptionsAddDialog'
import {LicensePolicyDiffSummary} from './LicensePolicyDiffSummary'

const ALLOWED_LICENSES = 'allowed-licenses'
const PACKAGE_EXCEPTIONS = 'package-exceptions'
const DIALOG_TYPE_PICKER = 'picker'
const DIALOG_TYPE_MANUAL_INPUT = 'manual-input'

const STATUS_BANNER_TITLES = {
  critical: 'Error',
  info: 'Info',
  success: 'Success',
} as const

type DraftSaveRevertMutationState = {
  isPending: boolean
  isError: boolean
  isSuccess: boolean
  error?: unknown
  reset: () => void
}

type DraftSaveRevertProps = {
  addCount: number
  deleteCount: number
  onSave: () => void
  onRevert: () => void
  resetOnRevert?: () => void
  saveMutation: DraftSaveRevertMutationState
}

interface LicensePolicyPageProps {
  title: string
  preview: boolean
  pageDescription: string
  licensesDescription: string
  exceptionsDescription: string
  data: LicensePolicyResponse
  enterpriseName?: string
  enterpriseSlug?: string
  policyName?: string
  pickerEnabled?: boolean
  addAllowedLicensesMutation?: AddAllowedLicensesMutation
  deleteAllowedLicensesMutation?: DeleteAllowedLicensesMutation
  addPackageExceptionsMutation?: AddPackageExceptionsMutation
  deletePackageExceptionsMutation?: DeletePackageExceptionsMutation
  failedSpdxIds?: string[]
  onDismissFailedSpdxIds?: () => void
  draftSaveRevert?: DraftSaveRevertProps
}

export function LicensePolicyPage({
  title,
  preview,
  pageDescription,
  licensesDescription,
  exceptionsDescription,
  data,
  enterpriseName,
  enterpriseSlug,
  policyName,
  pickerEnabled,
  addPackageExceptionsMutation,
  addAllowedLicensesMutation,
  deleteAllowedLicensesMutation,
  deletePackageExceptionsMutation,
  failedSpdxIds,
  onDismissFailedSpdxIds,
  draftSaveRevert,
}: LicensePolicyPageProps) {
  const editMode = usePolicyEditMode()
  const isDraftMode = editMode === PolicyEditMode.Draft
  const [activeDialog, setActiveDialog] = useState<typeof DIALOG_TYPE_PICKER | typeof DIALOG_TYPE_MANUAL_INPUT | null>(
    null,
  )
  const [searchParams] = useSearchParams()
  const selectedTab = searchParams.get('tab') || ALLOWED_LICENSES
  const {canManagePolicy} = useUserPermissions()

  const showSaveControls = Boolean(draftSaveRevert) && isDraftMode && canManagePolicy
  const changeCount = (draftSaveRevert?.addCount ?? 0) + (draftSaveRevert?.deleteCount ?? 0)
  const hasUnsavedChanges = showSaveControls && changeCount > 0
  const [revertStatus, setRevertStatus] = useState<'idle' | 'reverted' | 'no-changes'>('idle')
  const [lastSaveHadChanges, setLastSaveHadChanges] = useState<boolean | null>(null)

  // Adding licenses and private packages is only available from the Enterprise Policy edit mode when the user can manage the policy.
  const canAddPackage = !!addPackageExceptionsMutation && canManagePolicy // hides add package button for read-only users
  const canAddLicenses = !!addAllowedLicensesMutation && canManagePolicy // hides add licenses button for read-only users
  const allowedSpdxIds = useMemo(() => new Set(data.allowed.map(l => l.spdx_id)), [data.allowed])

  const allowedLicensesMenuItems: MenuItemConfig[] | undefined = canAddLicenses
    ? [
        ...(pickerEnabled ? [{label: 'Select from list', onSelect: () => setActiveDialog(DIALOG_TYPE_PICKER)}] : []),
        {label: 'Manual input', onSelect: () => setActiveDialog(DIALOG_TYPE_MANUAL_INPUT)},
      ]
    : undefined

  const [isDialogOpen, setIsDialogOpen] = useState(false)

  const dismissFailedLicensesBanner = useStableCallback(() => {
    onDismissFailedSpdxIds?.()
    addAllowedLicensesMutation?.reset()
  })

  useEffect(() => {
    if (selectedTab !== ALLOWED_LICENSES) {
      dismissFailedLicensesBanner()
    }
  }, [selectedTab, dismissFailedLicensesBanner])

  useBeforeUnload(
    useCallback(
      (event: BeforeUnloadEvent) => {
        if (hasUnsavedChanges) {
          event.preventDefault()
        }
      },
      [hasUnsavedChanges],
    ),
  )

  const statusBanner = useMemo(() => {
    if (!showSaveControls || !draftSaveRevert) return undefined

    if (revertStatus === 'reverted') {
      return {
        variant: 'success' as const,
        description: 'Unsaved changes reverted.',
        onDismiss: () => setRevertStatus('idle'),
      }
    }

    if (revertStatus === 'no-changes') {
      return {
        variant: 'info' as const,
        description: 'No changes to revert.',
        onDismiss: () => setRevertStatus('idle'),
      }
    }

    if (draftSaveRevert.saveMutation.isError) {
      const message =
        draftSaveRevert.saveMutation.error instanceof Error
          ? draftSaveRevert.saveMutation.error.message
          : 'Failed to save changes. Please try again.'
      return {
        variant: 'critical' as const,
        description: message,
      }
    }

    // Do not show a top-level save-success banner when invalid licenses were returned by the server.
    // Those are surfaced in the Licenses tab banner instead.
    if (draftSaveRevert.saveMutation.isSuccess && (failedSpdxIds?.length ?? 0) === 0) {
      const hadChanges = lastSaveHadChanges ?? true
      return hadChanges
        ? {
            variant: 'success' as const,
            description: 'License policy changes have been saved.',
            onDismiss: () => draftSaveRevert.saveMutation.reset(),
          }
        : {
            variant: 'info' as const,
            description: 'No changes made.',
            onDismiss: () => draftSaveRevert.saveMutation.reset(),
          }
    }

    return undefined
  }, [draftSaveRevert, failedSpdxIds, lastSaveHadChanges, revertStatus, showSaveControls])

  useAnnounceBanner(statusBanner?.description, {assertive: statusBanner?.variant === 'critical'})

  const handleSave = () => {
    if (!draftSaveRevert) return
    setRevertStatus('idle')
    setLastSaveHadChanges(draftSaveRevert.addCount + draftSaveRevert.deleteCount > 0)
    draftSaveRevert.onSave()
  }

  const handleRevert = () => {
    if (!draftSaveRevert) return
    const hadChangesBeforeRevert = draftSaveRevert.addCount + draftSaveRevert.deleteCount > 0
    draftSaveRevert.onRevert()
    draftSaveRevert.resetOnRevert?.()
    setRevertStatus(hadChangesBeforeRevert ? 'reverted' : 'no-changes')
    requestAnimationFrame(() => window.scrollTo({top: 0}))
  }

  return (
    <>
      <LicensePolicyHeader
        title={title}
        description={pageDescription}
        preview={preview}
        enterpriseName={enterpriseName}
        enterpriseSlug={enterpriseSlug}
      />

      {statusBanner && (
        <Banner
          variant={statusBanner.variant}
          className="mb-4"
          title={STATUS_BANNER_TITLES[statusBanner.variant]}
          description={statusBanner.description}
          hideTitle
          onDismiss={statusBanner.onDismiss}
        />
      )}

      {policyName !== undefined && (
        <FormControl className="mb-4" disabled>
          <FormControl.Label>Policy name</FormControl.Label>
          <TextInput value={policyName} />
        </FormControl>
      )}

      {/* Navigation tabs */}
      {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
      <UnderlineNav aria-label="License Policy Navigation" className={styles.UnderlineNav}>
        <UnderlineNav.Item
          as={Link}
          to={`?tab=${ALLOWED_LICENSES}`}
          aria-current={selectedTab === ALLOWED_LICENSES ? 'page' : undefined}
          counter={data.allowed.length || undefined}
        >
          Licenses
        </UnderlineNav.Item>
        <UnderlineNav.Item
          as={Link}
          to={`?tab=${PACKAGE_EXCEPTIONS}`}
          aria-current={selectedTab === PACKAGE_EXCEPTIONS ? 'page' : undefined}
          counter={data.packages.length || undefined}
        >
          Packages
        </UnderlineNav.Item>
      </UnderlineNav>

      {/* Licenses tab content */}
      {selectedTab === ALLOWED_LICENSES && (
        <>
          <LicensePolicyAllowedLicenses
            aria-label="Allowed licenses management"
            description={licensesDescription}
            licenses={data.allowed}
            datePolicyAdded={data.date_added}
            menuItems={allowedLicensesMenuItems}
            addAllowedLicensesMutation={addAllowedLicensesMutation}
            deleteAllowedLicensesMutation={deleteAllowedLicensesMutation}
            failedSpdxIds={failedSpdxIds}
            dismissFailedLicensesBanner={dismissFailedLicensesBanner}
          />

          {/* Modal dialog for adding new licenses via manual input */}
          {addAllowedLicensesMutation && (
            <LicensePolicyAddDialog
              isOpen={activeDialog === DIALOG_TYPE_MANUAL_INPUT}
              onClose={() => setActiveDialog(null)}
              addAllowedLicensesMutation={addAllowedLicensesMutation}
            />
          )}

          {addAllowedLicensesMutation && (
            <LicensePolicyPicker
              open={activeDialog === DIALOG_TYPE_PICKER}
              addAllowedLicensesMutation={addAllowedLicensesMutation}
              allowedSpdxIds={allowedSpdxIds}
              onClose={() => setActiveDialog(null)}
            />
          )}
        </>
      )}

      {/* Exceptions tab content */}
      {selectedTab === PACKAGE_EXCEPTIONS && (
        <>
          <LicensePolicyPackageExceptions
            aria-label="Package exceptions management"
            description={exceptionsDescription}
            packages={data.packages}
            deletePackageExceptionsMutation={deletePackageExceptionsMutation}
            onAddPackageClick={canAddPackage ? () => setIsDialogOpen(true) : undefined}
          />

          {canAddPackage && isDialogOpen && (
            <PackageExceptionsAddDialog
              onClose={() => setIsDialogOpen(false)}
              addPackageExceptionsMutation={addPackageExceptionsMutation}
            />
          )}
        </>
      )}

      {showSaveControls && draftSaveRevert && (
        <Stack direction="horizontal" wrap="wrap" gap="condensed" align="center" className="mt-1">
          <Button variant="primary" onClick={handleSave} loading={draftSaveRevert.saveMutation.isPending}>
            Save changes
          </Button>
          <Button onClick={handleRevert} disabled={draftSaveRevert.saveMutation.isPending}>
            Revert changes
          </Button>
          <LicensePolicyDiffSummary addCount={draftSaveRevert.addCount} deleteCount={draftSaveRevert.deleteCount} />
        </Stack>
      )}
    </>
  )
}
