import React, {createContext, use} from 'react'

export const PolicyEditMode = {
  Draft: 'DRAFT',
  Immediate: 'IMMEDIATE',
} as const
export type PolicyEditMode = (typeof PolicyEditMode)[keyof typeof PolicyEditMode]

const PolicyEditModeContext = createContext<PolicyEditMode | undefined>(undefined)

interface PolicyEditModeProviderProps {
  children: React.ReactNode
  mode: PolicyEditMode
}

export function PolicyEditModeProvider({children, mode}: PolicyEditModeProviderProps) {
  return <PolicyEditModeContext value={mode}>{children}</PolicyEditModeContext>
}

export function usePolicyEditMode(): PolicyEditMode {
  const context = use(PolicyEditModeContext)
  if (context === undefined) {
    throw new Error('usePolicyEditMode must be used within a PolicyEditModeProvider')
  }

  return context
}
