import {createContext, use, type PropsWithChildren} from 'react'

export interface EnterpriseInfoContextValue {
  enterpriseName?: string
  enterpriseSlug?: string
}

const EnterpriseInfoContext = createContext<EnterpriseInfoContextValue>({})

export function EnterpriseInfoProvider({children, ...props}: PropsWithChildren<EnterpriseInfoContextValue>) {
  return <EnterpriseInfoContext value={props}>{children}</EnterpriseInfoContext>
}

export function useEnterpriseInfo(): EnterpriseInfoContextValue {
  return use(EnterpriseInfoContext)
}
