import {useState} from 'react'
import {PackageIcon} from '@primer/octicons-react'
import {LicensePolicyDeleteDialog} from '../LicensePolicyPage/LicensePolicyDeleteDialog'
import {isWildcardPattern, type PackagePolicy} from '../../types/packages'
import {BaseList} from '../BaseListView/BaseList'
import {PackageExceptionsListItem} from './PackageExceptionsListItem'
import {PackageExceptionsFilter} from './PackageExceptionsFilter'
import {PolicyLevel} from '../../types/policy-levels'
import {PolicyEditMode, usePolicyEditMode} from '../../context/PolicyEditModeContext'
import {usePolicyLevel} from '../../context/PolicyLevelContext'
import {useUserPermissions} from '../../context/UserPermissionsContext'
import {ItemType} from '../../types/licenses'

interface PackageExceptionsListProps {
  packages: PackagePolicy[]
  deletePackageExceptionsMutation?: {
    mutate: (params: {packages: PackagePolicy[]}) => void
    error?: Error | null
    isError: boolean
    isPending: boolean
    reset: () => void
  }
}

export function PackageExceptionsList({packages, deletePackageExceptionsMutation}: PackageExceptionsListProps) {
  const level = usePolicyLevel()
  const {canManagePolicy} = useUserPermissions()
  const editMode = usePolicyEditMode()
  const isDraftMode = editMode === PolicyEditMode.Draft

  const [packagesToDelete, setPackagesToDelete] = useState<PackagePolicy[] | null>(null)
  const [clearSelectionCallback, setClearSelectionCallback] = useState<(() => void) | null>(null)

  // Filter function for package exceptions
  const filterPackages = (pkg: PackagePolicy, filterText: string): boolean => {
    return pkg.name.toLowerCase().includes(filterText.toLowerCase())
  }

  // Sort function for package exceptions (alphabetical, case-insensitive)
  const sortPackages = (a: PackagePolicy, b: PackagePolicy): number => {
    return a.name.toLowerCase().localeCompare(b.name.toLowerCase())
  }

  // Render function for each package item
  const renderPackageItem = (
    pkg: PackagePolicy,
    _index: number,
    isSelected: boolean,
    onSelect: () => void,
    itemKey: string,
  ) => (
    <PackageExceptionsListItem
      key={itemKey}
      packageName={pkg.name}
      packageManager={pkg.package_manager}
      spdxIDs={pkg.extra_allowed_spdx_ids}
      isSelected={isSelected}
      isWildcard={isWildcardPattern(pkg.name)}
      onSelect={onSelect}
      onDelete={canDeleteOne(pkg) ? () => handleDeleteOne(pkg) : undefined}
      hasCheckboxes={!!onBulkDelete}
    />
  )

  // Render function for search and filter
  const renderPackageFilter = (props: {
    filterText: string
    onFilterChange: (e: React.ChangeEvent<HTMLInputElement>) => void
  }) => <PackageExceptionsFilter filterText={props.filterText} onFilterChange={props.onFilterChange} />

  const getPackageKey = (pkg: PackagePolicy) => {
    return `${pkg.level}-${pkg.name}-${pkg.package_manager}`
  }

  const canDeleteOne = (pkg: PackagePolicy): boolean => {
    // Single-item delete is only supported at the repository policy level.
    if (level !== PolicyLevel.Repository) return false
    if (!canManagePolicy) return false
    return pkg.level === level
  }

  const handleDeleteOne = (pkg: PackagePolicy) => {
    if (!canDeleteOne(pkg)) return
    if (isDraftMode) {
      deletePackageExceptionsMutation?.mutate({packages: [pkg]})
      return
    }
    setPackagesToDelete([pkg])
  }

  const handleDeleteConfirm = () => {
    if (packagesToDelete) {
      deletePackageExceptionsMutation?.mutate({
        packages: packagesToDelete,
      })
    }
    // Clear selection after delete confirmation
    clearSelectionCallback?.()
    setClearSelectionCallback(null)
    setPackagesToDelete(null)
  }

  const handleDeleteCancel = () => {
    setClearSelectionCallback(null)
    setPackagesToDelete(null)
  }

  const onBulkDelete =
    level === PolicyLevel.Enterprise && canManagePolicy
      ? (selectedPackages: PackagePolicy[], clearSelection: () => void) => {
          if (isDraftMode) {
            deletePackageExceptionsMutation?.mutate({packages: selectedPackages})
            clearSelection()
            return
          }

          setPackagesToDelete(selectedPackages)
          setClearSelectionCallback(() => clearSelection)
        }
      : undefined

  const errorMessage = deletePackageExceptionsMutation?.error
    ? {
        title: 'Bulk delete package exceptions error',
        description:
          deletePackageExceptionsMutation.error.message || 'Failed to delete package exceptions. Please try again.',
      }
    : undefined

  return (
    <>
      <BaseList
        /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
        title="Package Exceptions List"
        items={packages}
        singleItemName="package"
        pluralItemName="packages"
        zeroItemsHeading="Allowed packages will appear here"
        zeroItemsDescription="Allow packages when you want to permit use of a package without adding its license to the policy"
        zeroItemsIcon={<PackageIcon size="medium" />}
        zeroItemsFilterHeading="No packages match your filter"
        filterFunction={filterPackages}
        sortFunction={sortPackages}
        renderFilter={renderPackageFilter}
        renderItem={renderPackageItem}
        getItemKey={getPackageKey}
        testId="package-exceptions-list"
        onBulkDelete={onBulkDelete}
        errorMessage={errorMessage}
      />
      {!isDraftMode && (
        <LicensePolicyDeleteDialog
          isOpen={packagesToDelete !== null}
          onClose={handleDeleteCancel}
          onConfirm={handleDeleteConfirm}
          policyLevel={level}
          itemType={ItemType.Package}
          itemName={packagesToDelete?.length === 1 ? packagesToDelete[0]?.name : undefined}
        />
      )}
    </>
  )
}
