import {ActionList, type ActionListGroupProps} from '@primer/react'
import {useSlots} from '@primer/react/experimental'
import {clsx} from 'clsx'
import React, {useId, useMemo} from 'react'

import styles from './BulkSelectorGroup.module.css'

export const BulkSelectorGroup: React.FC<
  Omit<ActionListGroupProps, 'selectionVariant' | 'onKeyDown'> & {
    itemsVisible?: boolean
    onClick?: React.MouseEventHandler<HTMLLIElement>
    onKeyDown?: React.KeyboardEventHandler<HTMLLIElement>
  }
> = ({
  title,
  className,
  'aria-label': ariaLabel,
  itemsVisible = true,
  id: externalId,
  onClick,
  onKeyDown,
  children,
  ...props
}) => {
  const generatedId = useId()
  const [slots, childrenWithoutSlots] = useSlots(children, {
    groupHeading: ActionList.GroupHeading,
  })

  let groupHeadingId = undefined

  // ActionList.GroupHeading
  if (slots.groupHeading) {
    // If there is an id prop passed in the ActionList.GroupHeading, use it otherwise use the generated id.
    groupHeadingId = slots.groupHeading.props.id ?? generatedId
  }

  // Supports the deprecated `title` prop
  if (title) {
    groupHeadingId = generatedId
  }

  const groupContextValue = useMemo(() => ({groupHeadingId}), [groupHeadingId])

  return (
    <li
      className={clsx(className, styles.Group)}
      data-items-hidden={itemsVisible ? undefined : ''}
      id={externalId}
      // eslint-disable-next-line jsx-a11y/role-has-required-aria-props -- using aria-checked instead because of indeterminate state
      role="treeitem"
      aria-level={1}
      tabIndex={-1}
      aria-expanded={itemsVisible}
      aria-label={ariaLabel ?? title ?? (slots.groupHeading?.props.children as string)}
      onClick={onClick}
      onKeyDown={onKeyDown}
      onFocus={e => {
        // Redirect focus from inner elements (e.g. GroupHeadingWrap) back to this <li>.
        // Child treeitems inside the [role="group"] list should keep their own focus.
        if (
          e.target !== e.currentTarget &&
          e.target.getAttribute('role') !== 'treeitem' &&
          !(e.target as HTMLElement).closest('[role="group"]')
        ) {
          e.currentTarget.focus()
        }
      }}
      {...props}
    >
      <ActionList.GroupContext value={groupContextValue}>
        {/* Supports new API ActionList.GroupHeading */}
        {/* eslint-disable-next-line @eslint-react/no-clone-element */}
        {!title && slots.groupHeading ? React.cloneElement(slots.groupHeading) : null}
        <div hidden={!itemsVisible} id={`${groupHeadingId}-content`}>
          <ul
            className={styles.GroupList}
            role="group"
            aria-label={ariaLabel ?? title ?? (slots.groupHeading?.props.children as string)}
          >
            {slots.groupHeading ? childrenWithoutSlots : children}
          </ul>
        </div>
      </ActionList.GroupContext>
    </li>
  )
}

BulkSelectorGroup.displayName = 'BulkSelectorGroup'
;(BulkSelectorGroup as typeof BulkSelectorGroup & {__SLOT__?: symbol}).__SLOT__ = ActionList.Group.__SLOT__
