import {mainQuery} from '@github-ui/react-core/future/main-query'
import {licensePolicyAppBuilder} from '../config/app-builder'
import type {
  EnterpriseLicensePolicyResponse,
  EnterpriseSingleLicensePolicyResponse,
  RepositoryLicensePolicyResponse,
} from '../types/policies'

export const enterpriseLicensePolicyRoute = licensePolicyAppBuilder.createQueryRouteConfig(
  'enterpriseLicensePolicyRoute',
  {
    path: '/enterprises/:business/settings/advanced_security/license_policy',
    queries: [mainQuery<EnterpriseLicensePolicyResponse>()],
  },
)

export const enterpriseSingleLicensePolicyRoute = licensePolicyAppBuilder.createQueryRouteConfig(
  'enterpriseSingleLicensePolicyRoute',
  {
    path: '/enterprises/:business/settings/advanced_security/license_policy/default',
    queries: [mainQuery<EnterpriseSingleLicensePolicyResponse>()],
  },
)

export const repositoryLicensePolicyRoute = licensePolicyAppBuilder.createQueryRouteConfig(
  'repositoryLicensePolicyRoute',
  {
    path: '/:organization/:repository/security/advanced_security/license_policy',
    queries: [mainQuery<RepositoryLicensePolicyResponse>()],
  },
)
