import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {licensePolicyAppBuilder} from './config/app-builder'

import {
  enterpriseLicensePolicyRoute,
  enterpriseSingleLicensePolicyRoute,
  repositoryLicensePolicyRoute,
} from './routes/license-policy-route'
import {EnterpriseLicensePolicy} from './routes/EnterpriseLicensePolicy'
import {EnterpriseSingleLicensePolicy} from './routes/EnterpriseSingleLicensePolicy'
import {RepositoryLicensePolicy} from './routes/RepositoryLicensePolicy'

export const licensePolicyApp = licensePolicyAppBuilder.createDataRouterAppFromRoutes([
  enterpriseLicensePolicyRoute.toRoute({Component: EnterpriseLicensePolicy}),
  enterpriseSingleLicensePolicyRoute.toRoute({Component: EnterpriseSingleLicensePolicy}),
  repositoryLicensePolicyRoute.toRoute({Component: RepositoryLicensePolicy}),
])
registerDataRouterApp(licensePolicyApp)
