import {useCallback, useReducer} from 'react'

import type {PackagePolicy} from '../types/packages'
import {PolicyLevel} from '../types/policy-levels'

type DraftState = {
  upstreamKey: string
  originalPackageKeys: string[]
  allPackages: PackagePolicy[]
  addPackages: PackagePolicy[]
  deletePackages: PackagePolicy[]
  level: PolicyLevel
}

type DraftAction =
  | {type: 'init_from_upstream'; upstreamKey: string; packages: PackagePolicy[]; level: PolicyLevel}
  | {type: 'stage_add_packages'; packages: PackagePolicy[]}
  | {type: 'stage_delete_packages'; packages: PackagePolicy[]}

function draftReducer(state: DraftState, action: DraftAction): DraftState {
  switch (action.type) {
    case 'init_from_upstream': {
      const originalPackageKeys = uniqStrings(action.packages.map(getPackageKey))
      return {
        upstreamKey: action.upstreamKey,
        originalPackageKeys,
        allPackages: action.packages,
        addPackages: [],
        deletePackages: [],
        level: action.level,
      }
    }
    case 'stage_add_packages': {
      if (state.level === PolicyLevel.Repository) return state

      // Normalize and dedupe packages being added.
      const normalized = normalizePackages(action.packages)
      if (normalized.length === 0) return state

      // The set of packages currently in the draft (including staged adds and excluding staged deletes)
      const existingPackages = new Set(state.allPackages.map(getPackageKey))
      // Only consider packages that aren't already in the draft.
      const toAdd = normalized.filter(pkg => !existingPackages.has(getPackageKey(pkg)))
      if (toAdd.length === 0) return state

      // The set of packages without any edits applied.
      const originalPackages = new Set(state.originalPackageKeys)

      // Only consider staging an add for packages that aren't in the original policy.
      const stagedAdds = toAdd.filter(pkg => !originalPackages.has(getPackageKey(pkg)))

      const toAddKeys = new Set(toAdd.map(getPackageKey))

      return {
        ...state,
        // add packages not already in the draft
        allPackages: [...state.allPackages, ...toAdd],
        // only stage add for packages not in the original policy
        addPackages: uniqPackagesByKey([...state.addPackages, ...stagedAdds]),
        // if a package was staged for delete, un-stage that delete since we're adding it back in this draft session
        deletePackages: state.deletePackages.filter(pkg => !toAddKeys.has(getPackageKey(pkg))),
      }
    }

    case 'stage_delete_packages': {
      // Normalize and dedupe packages being deleted.
      const normalized = normalizePackages(action.packages)
      if (normalized.length === 0) return state

      // The set of packages currently in the draft (including staged adds and excluding staged deletes)
      const existingPackages = new Set(state.allPackages.map(getPackageKey))

      // In repository mode, only repository-level packages can be deleted.
      const deletablePackages =
        state.level === PolicyLevel.Repository
          ? new Set(
              state.allPackages.filter(pkg => pkg.level === PolicyLevel.Repository).map(pkg => getPackageKey(pkg)),
            )
          : existingPackages

      // Only consider packages that are in the draft.
      const toDelete = normalized.filter(pkg => deletablePackages.has(getPackageKey(pkg)))
      const keysToDelete = new Set(toDelete.map(getPackageKey))
      if (toDelete.length === 0) return state

      // The set of packages without any edits applied.
      const originalPackages = new Set(state.originalPackageKeys)

      // Only consider staging a delete for packages that are in the original policy.
      const stagedDeletes = toDelete.filter(pkg => originalPackages.has(getPackageKey(pkg)))

      return {
        ...state,
        // delete packages from the draft
        allPackages: state.allPackages.filter(pkg => !keysToDelete.has(getPackageKey(pkg))),
        // only stage delete for packages in the original policy
        deletePackages: uniqPackagesByKey([...state.deletePackages, ...stagedDeletes]),
        // if a package was staged for add, un-stage that add since we're deleting it in this draft session
        addPackages: state.addPackages.filter(pkg => !keysToDelete.has(getPackageKey(pkg))),
      }
    }
  }
}

/**
 * Keeps a local, mutable copy of the policy's package exceptions.
 *
 * The `allPackages` state is initialized from the route payload on mount and
 * re-initialized if the upstream payload meaningfully changes (e.g. after a
 * successful mutation invalidates + refetches the route query).
 */
type PolicyPackagesDraftStateBase = {
  allPackages: PackagePolicy[]
  deletePackages: PackagePolicy[]
  stageDeletePackages: (packages: PackagePolicy[]) => void
  resetPackagesFromUpstream: () => void
}

type PolicyPackagesDraftStateWithAdd = PolicyPackagesDraftStateBase & {
  addPackages: PackagePolicy[]
  stageAddPackages: (packages: PackagePolicy[]) => void
}

export function usePolicyPackagesDraftState(
  level: typeof PolicyLevel.Repository,
  initialPackages: PackagePolicy[],
): PolicyPackagesDraftStateBase
export function usePolicyPackagesDraftState(
  level: Exclude<PolicyLevel, typeof PolicyLevel.Repository>,
  initialPackages: PackagePolicy[],
): PolicyPackagesDraftStateWithAdd
export function usePolicyPackagesDraftState(
  level: PolicyLevel,
  initialPackages: PackagePolicy[],
): PolicyPackagesDraftStateBase | PolicyPackagesDraftStateWithAdd {
  const upstreamKey = policyPackagesUpstreamKey(level, initialPackages)

  const [state, dispatch] = useReducer(draftReducer, initialPackages, packages => ({
    upstreamKey: policyPackagesUpstreamKey(level, packages),
    originalPackageKeys: uniqStrings(packages.map(getPackageKey)),
    allPackages: packages,
    addPackages: [],
    deletePackages: [],
    level,
  }))

  // If the server payload changes (not just a new array reference), reset local state.
  if (state.upstreamKey !== upstreamKey) {
    dispatch({type: 'init_from_upstream', upstreamKey, packages: initialPackages, level})
  }

  const stageAddPackages = useCallback((packages: PackagePolicy[]) => {
    dispatch({type: 'stage_add_packages', packages})
  }, [])

  const stageDeletePackages = useCallback((packages: PackagePolicy[]) => {
    dispatch({type: 'stage_delete_packages', packages})
  }, [])

  const resetPackagesFromUpstream = useCallback(() => {
    dispatch({type: 'init_from_upstream', upstreamKey, packages: initialPackages, level})
  }, [initialPackages, level, upstreamKey])

  const base: PolicyPackagesDraftStateBase = {
    allPackages: state.allPackages,
    deletePackages: state.deletePackages,
    stageDeletePackages,
    resetPackagesFromUpstream,
  }

  if (level === PolicyLevel.Repository) return base

  return {
    ...base,
    addPackages: state.addPackages,
    stageAddPackages,
  }
}

function packagesKey(packages: PackagePolicy[]) {
  return packages.map(getPackageKey).join('\u0000')
}

function policyPackagesUpstreamKey(level: PolicyLevel, packages: PackagePolicy[]) {
  return `${level}\u0000${packagesKey(packages)}`
}

function getPackageKey(pkg: PackagePolicy) {
  return `${pkg.package_manager}\u0000${pkg.name}`
}

function uniqStrings(values: string[]) {
  return Array.from(new Set(values))
}

function uniqPackagesByKey(values: PackagePolicy[]) {
  const seen = new Set<string>()
  const out: PackagePolicy[] = []

  for (const pkg of values) {
    const key = getPackageKey(pkg)
    if (seen.has(key)) continue
    seen.add(key)
    out.push(pkg)
  }

  return out
}

function normalizePackages(values: PackagePolicy[]) {
  const normalized = values
    .map(pkg => ({
      ...pkg,
      name: pkg.name.trim(),
    }))
    .filter(pkg => pkg.name.length > 0 && pkg.package_manager.trim().length > 0)

  return uniqPackagesByKey(normalized)
}

export function createStagedPackageException({
  name,
  packageManager,
  level,
}: {
  name: string
  packageManager: string
  level: Exclude<PolicyLevel, typeof PolicyLevel.Repository>
}): PackagePolicy {
  return {
    name: name.trim(),
    package_manager: packageManager,
    extra_allowed_spdx_ids: [],
    level,
  }
}
