import {PageHeader, Button, ActionMenu, ActionList} from '@primer/react'
import type {ComponentProps} from 'react'

import {PolicyEditMode, usePolicyEditMode} from '../../context/PolicyEditModeContext'

export interface MenuItemConfig {
  label: string
  onSelect: () => void
}

interface BaseListHeaderProps {
  title: string
  description: string
  addButtonLabel?: string
  onAddClick?: () => void
  menuItems?: MenuItemConfig[]
}

export function BaseListHeader({
  title,
  description,
  addButtonLabel = 'Add',
  onAddClick,
  menuItems,
  ...props
}: BaseListHeaderProps & Omit<ComponentProps<typeof PageHeader>, 'role' | 'children'>) {
  const hasMenuItems = (menuItems?.length ?? 0) > 0
  const editMode = usePolicyEditMode()
  const addButtonVariant = editMode === PolicyEditMode.Draft ? 'default' : 'primary'

  return (
    <>
      {/* Section header with add button */}
      <PageHeader role="group" {...props}>
        <PageHeader.TitleArea>
          <PageHeader.Title as="h2" className="h3-override-shared-component">
            {title}
          </PageHeader.Title>
        </PageHeader.TitleArea>
        <PageHeader.Actions>
          {/* add button with drop down menu*/}
          {hasMenuItems && (
            <ActionMenu>
              <ActionMenu.Button variant={addButtonVariant}>{addButtonLabel}</ActionMenu.Button>
              <ActionMenu.Overlay>
                <ActionList>
                  {menuItems?.map(item => (
                    <ActionList.Item key={item.label} onSelect={item.onSelect}>
                      {item.label}
                    </ActionList.Item>
                  ))}
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          )}
          {/* plain add button without a drop down menu*/}
          {onAddClick && !hasMenuItems && (
            <Button variant={addButtonVariant} onClick={onAddClick}>
              {addButtonLabel}
            </Button>
          )}
        </PageHeader.Actions>
      </PageHeader>

      <PageHeader.Description className="color-fg-muted tmp-mb-3">{description}</PageHeader.Description>
    </>
  )
}
