import {Stack} from '@primer/react'

import pluralize from 'pluralize'

export type LicensePolicyDiffSummaryProps = {
  addCount: number
  deleteCount: number
}

export function LicensePolicyDiffSummary({addCount, deleteCount}: LicensePolicyDiffSummaryProps) {
  if (addCount === 0 && deleteCount === 0) {
    return null
  }

  return (
    <Stack direction="horizontal" align="center" gap="tight" className="ml-2">
      {addCount > 0 && <span className="color-fg-success">+{addCount}</span>}
      {deleteCount > 0 && <span className="color-fg-danger">-{deleteCount}</span>}
      <span className="color-fg-muted">{pluralize('unsaved change', addCount + deleteCount)}</span>
    </Stack>
  )
}
