import {Label, Link, PageHeader} from '@primer/react'

export const LicensePolicyOverviewHeader = ({isPreview}: {isPreview?: boolean}) => {
  const docsUrl = isPreview
    ? 'https://docs.github.com/en/enterprise-cloud@latest/early-access/code-security/supply-chain-security/enforcing-license-policy-across-an-enterprise'
    : 'https://docs.github.com/code-security/supply-chain-security/understanding-your-software-supply-chain/enforcing-license-policy-across-an-enterprise'

  return (
    <>
      <PageHeader hasBorder>
        <PageHeader.TitleArea>
          <PageHeader.Title as="h1">License compliance</PageHeader.Title>

          {isPreview && (
            <PageHeader.TrailingVisual>
              <Label variant="success">Preview</Label>
            </PageHeader.TrailingVisual>
          )}
        </PageHeader.TitleArea>
      </PageHeader>

      <PageHeader.Description>
        <span>
          License compliance will only apply to repositories with GitHub Advanced Security and license policy
          enforcement enabled across all organizations in this enterprise.{' '}
          <Link inline href={docsUrl}>
            Learn more about license policies
          </Link>
          .
        </span>
      </PageHeader.Description>
    </>
  )
}
