import {PageHeader, Link, Stack} from '@primer/react'
import {ShieldLockIcon} from '@primer/octicons-react'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import {clsx} from 'clsx'

import styles from './LicensePolicyHeader.module.css'

interface LicensePolicyHeader {
  title: string
  description: string
  preview: boolean
  enterpriseName?: string
  enterpriseSlug?: string
}

export function LicensePolicyHeader({
  title,
  description,
  preview,
  enterpriseName,
  enterpriseSlug,
}: LicensePolicyHeader) {
  const docsUrl = preview
    ? 'https://docs.github.com/en/enterprise-cloud@latest/early-access/code-security/supply-chain-security/enforcing-license-policy-across-an-enterprise'
    : 'https://docs.github.com/code-security/supply-chain-security/understanding-your-software-supply-chain/enforcing-license-policy-across-an-enterprise'
  return (
    <>
      {/* Main page header with title and description */}
      {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
      <PageHeader hasBorder aria-label="License Policy">
        <PageHeader.TitleArea>
          <PageHeader.Title as="h1" className="h1-override-shared-component">
            {title}
          </PageHeader.Title>
          {preview && (
            <PageHeader.TrailingVisual>
              <BetaLabel>Preview</BetaLabel>
            </PageHeader.TrailingVisual>
          )}
        </PageHeader.TitleArea>
      </PageHeader>

      <Stack direction="horizontal" justify="space-between" gap="spacious" align="start">
        <PageHeader.Description className="color-fg-muted tmp-mb-4">
          <span>
            {description}{' '}
            <Link inline href={docsUrl}>
              Learn more about license policies.
            </Link>
          </span>
        </PageHeader.Description>
        {enterpriseName && enterpriseSlug && (
          <span className={clsx(styles.managedBy, 'color-fg-muted')}>
            <ShieldLockIcon size={16} aria-hidden="true" />
            <span> Managed by </span>
            <Link inline href={`/enterprises/${enterpriseSlug}`}>
              {enterpriseName}
            </Link>
          </span>
        )}
      </Stack>
    </>
  )
}
